PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX session_user ON sessions(user_id);
CREATE TABLE projects (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, updated_at TEXT NOT NULL, created_at TEXT NOT NULL, last_thread_id TEXT, cover_url TEXT, canvas TEXT NOT NULL DEFAULT '{"revision":0,"elements":[],"files":{}}', event_seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE threads (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), thread_id TEXT NOT NULL REFERENCES threads(id), user_id TEXT NOT NULL REFERENCES users(id), state TEXT NOT NULL CHECK(state IN ('queued','planning','running','waiting_input','completed','failed','cancelled')), frozen_submission TEXT NOT NULL, effective_settings TEXT, contents TEXT NOT NULL DEFAULT '[]', pending_calls TEXT NOT NULL DEFAULT '[]', tool_count INTEGER NOT NULL DEFAULT 0, started_at INTEGER NOT NULL, created_at TEXT NOT NULL, error TEXT, resume_phase TEXT NOT NULL DEFAULT 'planning');
CREATE UNIQUE INDEX thread_one_active_run ON runs(thread_id) WHERE state IN ('queued','planning','running','waiting_input');
CREATE TABLE messages (ordinal INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), thread_id TEXT NOT NULL REFERENCES threads(id), run_id TEXT REFERENCES runs(id), role TEXT NOT NULL, parts TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE idempotency (user_id TEXT NOT NULL REFERENCES users(id), scope TEXT NOT NULL, key TEXT NOT NULL, hash TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(user_id,scope,key));
CREATE TABLE tasks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), run_id TEXT NOT NULL REFERENCES runs(id), user_id TEXT NOT NULL REFERENCES users(id), tool_invocation_id TEXT NOT NULL, operation TEXT NOT NULL, slot_index INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','submitted','running','ingesting','committed','failed','cancelled')), input TEXT NOT NULL, output TEXT, error TEXT, attempt INTEGER NOT NULL DEFAULT 0, cancel_requested INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(run_id,tool_invocation_id,slot_index));
CREATE TABLE submit_intents (task_id TEXT PRIMARY KEY REFERENCES tasks(id), attempt INTEGER NOT NULL, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('prepared','sent','acknowledged','rejected','unknown')), updated_at TEXT NOT NULL);
CREATE TABLE assets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), project_id TEXT REFERENCES projects(id), storage_key TEXT NOT NULL, mime TEXT NOT NULL, byte_length INTEGER NOT NULL, sha256 TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX asset_hash ON assets(user_id,sha256);
CREATE TABLE appearance_snapshots (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), project_id TEXT REFERENCES projects(id), source_asset_id TEXT NOT NULL REFERENCES assets(id), asset_id TEXT NOT NULL REFERENCES assets(id), render_key TEXT NOT NULL, request_hash TEXT NOT NULL, appearance TEXT NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, UNIQUE(user_id,render_key));
CREATE TABLE artifacts (id TEXT PRIMARY KEY, task_id TEXT NOT NULL UNIQUE REFERENCES tasks(id), asset_id TEXT NOT NULL REFERENCES assets(id), snapshot_id TEXT NOT NULL REFERENCES appearance_snapshots(id), provider_parts TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE insertions (task_id TEXT PRIMARY KEY REFERENCES tasks(id), project_id TEXT NOT NULL REFERENCES projects(id), artifact_id TEXT NOT NULL REFERENCES artifacts(id), element_ids TEXT NOT NULL, canvas_revision INTEGER NOT NULL);
CREATE TABLE events (project_id TEXT NOT NULL REFERENCES projects(id), seq INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(project_id,seq));
CREATE TABLE operations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), client_op_id TEXT NOT NULL, request_hash TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('user','agent','task')), before_revision INTEGER NOT NULL, after_revision INTEGER NOT NULL, changes TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,client_op_id));
CREATE TABLE element_revisions (project_id TEXT NOT NULL REFERENCES projects(id), element_id TEXT NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY(project_id,element_id));
CREATE TABLE quota_usage (day TEXT NOT NULL, subject TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(day,subject));
CREATE TABLE quota_reservations (task_id TEXT PRIMARY KEY, day TEXT NOT NULL, user_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('reserved','counted','released')));
CREATE TABLE input_requests (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), run_id TEXT NOT NULL REFERENCES runs(id), payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', call TEXT, answer TEXT);
CREATE TABLE auth_rate_limits (key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE outbox (task_id TEXT PRIMARY KEY REFERENCES tasks(id), sent_at INTEGER);
